using System.Diagnostics;
using Microsoft.Extensions.AI;
using OpenTelemetry;
using OpenTelemetry.Trace;
using Xunit;

namespace MyApp.Evals;

/// <summary>
/// Validates that agent interactions produce the expected OpenTelemetry spans and attributes.
/// </summary>
public class TelemetryTests
{
    [Fact]
    public async Task Agent_EmitsExpectedSpans()
    {
        var exportedActivities = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddInMemoryExporter(exportedActivities)
            .Build();

        IChatClient client = new ChatClientBuilder(new TestChatClient())
            .UseOpenTelemetry()
            .Build();

        await client.GetResponseAsync("Help me with time management.");

        tracerProvider.ForceFlush();

        Assert.NotEmpty(exportedActivities);

        var chatSpan = exportedActivities.FirstOrDefault(a => a.OperationName.Contains("chat"));
        Assert.NotNull(chatSpan);
        Assert.Equal(ActivityStatusCode.Unset, chatSpan.Status);
    }

    [Fact]
    public async Task Agent_SpansHaveGenAiAttributes()
    {
        var exportedActivities = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddInMemoryExporter(exportedActivities)
            .Build();

        IChatClient client = new ChatClientBuilder(new TestChatClient())
            .UseOpenTelemetry()
            .Build();

        await client.GetResponseAsync("What are good study habits?");

        tracerProvider.ForceFlush();

        var span = exportedActivities.First();
        var tags = span.Tags.ToDictionary(t => t.Key, t => t.Value);
        Assert.True(tags.ContainsKey("gen_ai.system") || tags.ContainsKey("gen_ai.request.model"),
            "Expected gen_ai semantic convention attributes on span.");
    }

    [Fact]
    public async Task Agent_NoErrorSpans()
    {
        var exportedActivities = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddInMemoryExporter(exportedActivities)
            .Build();

        IChatClient client = new ChatClientBuilder(new TestChatClient())
            .UseOpenTelemetry()
            .Build();

        await client.GetResponseAsync("Give me a quick productivity tip.");

        tracerProvider.ForceFlush();

        Assert.All(exportedActivities, a =>
            Assert.NotEqual(ActivityStatusCode.Error, a.Status));
    }
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Xunit;

namespace MyApp.Evals;

/// <summary>
/// Evaluates agent response quality using LLM-as-judge metrics.
/// </summary>
public class QualityTests
{
    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };

    [Fact]
    public async Task Responses_MeetRelevanceThreshold()
    {
        var scenarios = LoadScenarios();
        IChatClient judge = new TestChatClient(qualityScore: 4);

        foreach (var scenario in scenarios)
        {
            var userMessage = scenario.Input.Messages.Last(m => m.Role == "user").Content;
            var response = await GetAgentResponse(userMessage);

            var score = await EvaluateRelevance(judge, userMessage, response);
            Assert.True(score >= 3.5, $"Scenario '{scenario.Name}' relevance {score} below threshold 3.5");
        }
    }

    [Fact]
    public async Task Responses_MeetCompletenessThreshold()
    {
        var scenarios = LoadScenarios();
        IChatClient judge = new TestChatClient(qualityScore: 4);

        foreach (var scenario in scenarios)
        {
            var userMessage = scenario.Input.Messages.Last(m => m.Role == "user").Content;
            var response = await GetAgentResponse(userMessage);

            var score = await EvaluateCompleteness(judge, userMessage, response);
            Assert.True(score >= 3.0, $"Scenario '{scenario.Name}' completeness {score} below threshold 3.0");
        }
    }

    [Fact]
    public async Task Responses_MeetMinimumLength()
    {
        var scenarios = LoadScenarios();

        foreach (var scenario in scenarios)
        {
            var userMessage = scenario.Input.Messages.Last(m => m.Role == "user").Content;
            var response = await GetAgentResponse(userMessage);

            var minLength = scenario.Expected.MinLength;
            Assert.True(response.Length >= minLength,
                $"Scenario '{scenario.Name}' response length {response.Length} below minimum {minLength}");
        }
    }

    private static async Task<string> GetAgentResponse(string userMessage)
    {
        IChatClient client = new TestChatClient();
        var result = await client.GetResponseAsync(userMessage);
        return result.Text;
    }

    private static async Task<double> EvaluateRelevance(IChatClient judge, string query, string response)
    {
        // Simulated LLM-as-judge evaluation
        var result = await judge.GetResponseAsync(
            $"Rate relevance 1-5 of this response to the query.\nQuery: {query}\nResponse: {response}");
        return ParseScore(result.Text);
    }

    private static async Task<double> EvaluateCompleteness(IChatClient judge, string query, string response)
    {
        var result = await judge.GetResponseAsync(
            $"Rate completeness 1-5 of this response.\nQuery: {query}\nResponse: {response}");
        return ParseScore(result.Text);
    }

    private static double ParseScore(string text)
    {
        if (double.TryParse(text.Trim(), out var score))
            return score;
        return 3.0;
    }

    private static List<Scenario> LoadScenarios()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "datasets", "scenarios.json");
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<List<Scenario>>(json, JsonOptions)!;
    }
}

public record Scenario(string Id, string Name, ScenarioInput Input, ScenarioExpected Expected);
public record ScenarioInput(List<ScenarioMessage> Messages);
public record ScenarioMessage(string Role, string Content);
public record ScenarioExpected(List<string>? Contains = null, int MinLength = 0, bool ShouldClarify = false);

using System.Text.Json;
using Microsoft.Extensions.AI;
using Xunit;

namespace MyApp.Evals;

/// <summary>
/// Compares agent responses across model configurations (baseline vs candidates).
/// </summary>
public class CompareTests
{
    [Fact]
    public async Task Compare_BaselineVsCandidate_ProducesResults()
    {
        var scenarios = LoadScenarios();
        var results = new List<ComparisonResult>();

        IChatClient baseline = new TestChatClient(label: "gpt-4o-mini");
        IChatClient candidate = new TestChatClient(label: "gpt-4o");

        foreach (var scenario in scenarios)
        {
            var userMessage = scenario.Input.Messages.Last(m => m.Role == "user").Content;

            var sw = System.Diagnostics.Stopwatch.StartNew();
            var baselineResponse = await baseline.GetResponseAsync(userMessage);
            var baselineLatency = sw.ElapsedMilliseconds;

            sw.Restart();
            var candidateResponse = await candidate.GetResponseAsync(userMessage);
            var candidateLatency = sw.ElapsedMilliseconds;

            results.Add(new ComparisonResult(
                ScenarioId: scenario.Id,
                ScenarioName: scenario.Name,
                BaselineResponse: baselineResponse.Text,
                CandidateResponse: candidateResponse.Text,
                BaselineLatencyMs: baselineLatency,
                CandidateLatencyMs: candidateLatency));
        }

        Assert.NotEmpty(results);
        Assert.All(results, r =>
        {
            Assert.False(string.IsNullOrWhiteSpace(r.BaselineResponse));
            Assert.False(string.IsNullOrWhiteSpace(r.CandidateResponse));
        });

        // Write comparison output
        var outputDir = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "evals", "results");
        Directory.CreateDirectory(outputDir);
        var outputPath = Path.Combine(outputDir, "comparison.json");
        var json = JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        await File.WriteAllTextAsync(outputPath, json);
    }

    [Fact]
    public async Task Compare_CandidateNotWorseThanBaseline()
    {
        IChatClient baseline = new TestChatClient(label: "gpt-4o-mini");
        IChatClient candidate = new TestChatClient(label: "gpt-4o");

        var scenarios = LoadScenarios();

        foreach (var scenario in scenarios)
        {
            var userMessage = scenario.Input.Messages.Last(m => m.Role == "user").Content;

            var baselineResponse = await baseline.GetResponseAsync(userMessage);
            var candidateResponse = await candidate.GetResponseAsync(userMessage);

            // Candidate response should be at least as long as baseline (proxy for quality)
            Assert.True(candidateResponse.Text.Length >= baselineResponse.Text.Length * 0.8,
                $"Scenario '{scenario.Name}': candidate response significantly shorter than baseline.");
        }
    }

    private static List<Scenario> LoadScenarios()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "datasets", "scenarios.json");
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<List<Scenario>>(json, new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;
    }
}

public record ComparisonResult(
    string ScenarioId,
    string ScenarioName,
    string BaselineResponse,
    string CandidateResponse,
    long BaselineLatencyMs,
    long CandidateLatencyMs);

using Microsoft.Extensions.AI;

namespace MyApp.Evals;

/// <summary>
/// A deterministic test double for IChatClient used in eval tests.
/// Avoids live API calls while exercising the full pipeline.
/// </summary>
public sealed class TestChatClient : IChatClient
{
    private readonly string _label;
    private readonly int _qualityScore;

    public TestChatClient(string label = "test", int qualityScore = 4)
    {
        _label = label;
        _qualityScore = qualityScore;
    }

    public ChatClientMetadata Metadata => new(nameof(TestChatClient), modelId: _label);

    public async Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        await Task.CompletedTask;
        var userMessage = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";

        var response = GenerateResponse(userMessage);
        return new ChatResponse(new ChatMessage(ChatRole.Assistant, response));
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        throw new NotSupportedException("Streaming not used in evals.");
    }

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }

    private string GenerateResponse(string userMessage)
    {
        if (userMessage.Contains("relevance", StringComparison.OrdinalIgnoreCase) ||
            userMessage.Contains("completeness", StringComparison.OrdinalIgnoreCase) ||
            userMessage.Contains("Rate", StringComparison.OrdinalIgnoreCase))
        {
            return _qualityScore.ToString();
        }

        if (userMessage.Contains("time management", StringComparison.OrdinalIgnoreCase))
        {
            return "Here are effective time management strategies: First, prioritize tasks using the Eisenhower matrix. " +
                   "Second, create a daily schedule with time blocks. Third, eliminate distractions during focused work periods. " +
                   "Consider using the Pomodoro technique for sustained concentration.";
        }

        if (userMessage.Contains("losing focus", StringComparison.OrdinalIgnoreCase))
        {
            return "When you lose focus after the first week, it often means the habit hasn't solidified yet. " +
                   "Build a consistent routine by anchoring new behaviors to existing ones. " +
                   "Track your progress visually to maintain motivation.";
        }

        if (userMessage.Contains("better", StringComparison.OrdinalIgnoreCase) && userMessage.Length < 30)
        {
            return "I'd love to help you improve! Could you tell me more about what area you'd like to focus on? " +
                   "For example, are you looking to improve productivity, communication, health, or something else?";
        }

        return "I'm here to help you with coaching and personal development. " +
               "Let me know what specific area you'd like guidance on, and I'll provide tailored strategies.";
    }
}

