using Microsoft.Extensions.AI;

namespace MyApp.Evals;

/// <summary>
/// A deterministic test double for IChatClient used in eval tests.
/// Avoids live API calls while exercising the full pipeline.
/// </summary>
public sealed class TestChatClient : IChatClient
{
    private readonly string _label;
    private readonly int _qualityScore;

    public TestChatClient(string label = "test", int qualityScore = 4)
    {
        _label = label;
        _qualityScore = qualityScore;
    }

    public ChatClientMetadata Metadata => new(nameof(TestChatClient), modelId: _label);

    public async Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        await Task.CompletedTask;
        var userMessage = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";

        var response = GenerateResponse(userMessage);
        return new ChatResponse(new ChatMessage(ChatRole.Assistant, response));
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        throw new NotSupportedException("Streaming not used in evals.");
    }

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }

    private string GenerateResponse(string userMessage)
    {
        if (userMessage.Contains("relevance", StringComparison.OrdinalIgnoreCase) ||
            userMessage.Contains("completeness", StringComparison.OrdinalIgnoreCase) ||
            userMessage.Contains("Rate", StringComparison.OrdinalIgnoreCase))
        {
            return _qualityScore.ToString();
        }

        if (userMessage.Contains("time management", StringComparison.OrdinalIgnoreCase))
        {
            return "Here are effective time management strategies: First, prioritize tasks using the Eisenhower matrix. " +
                   "Second, create a daily schedule with time blocks. Third, eliminate distractions during focused work periods. " +
                   "Consider using the Pomodoro technique for sustained concentration.";
        }

        if (userMessage.Contains("losing focus", StringComparison.OrdinalIgnoreCase))
        {
            return "When you lose focus after the first week, it often means the habit hasn't solidified yet. " +
                   "Build a consistent routine by anchoring new behaviors to existing ones. " +
                   "Track your progress visually to maintain motivation.";
        }

        if (userMessage.Contains("better", StringComparison.OrdinalIgnoreCase) && userMessage.Length < 30)
        {
            return "I'd love to help you improve! Could you tell me more about what area you'd like to focus on? " +
                   "For example, are you looking to improve productivity, communication, health, or something else?";
        }

        return "I'm here to help you with coaching and personal development. " +
               "Let me know what specific area you'd like guidance on, and I'll provide tailored strategies.";
    }
}

